draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  // tree
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W / 2, 50);
  ctx.lineTo(W / 2, H / 2);
  ctx.stroke();
  // apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W / 2, 70 + Math.sin(t) * 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.stroke();
  // antioxidants
  ctx.fillStyle = 'blue';
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Antioxidants', W / 2, H / 2 + 30 + Math.sin(t + Math.PI / 2) * 20);
  ctx.restore();
}
